import{_ as o,l as r,o as e,c as n,v as t,p as s,x as i,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"借券费率","description":"","frontmatter":{"title":"借券费率","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/stock-loan-fee.md","filePath":"quant/stock-loan-fee.md","lastUpdated":1789023840000}'),h={name:"quant/stock-loan-fee.md"};function E(B,a,u,A,_,f){const l=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="借券费率" tabindex="-1">借券费率 <a class="header-anchor" href="#借券费率" aria-label="Permalink to &quot;借券费率&quot;">​</a></h1><div class="epigraph"><p>能借到只解决资格；费率决定空头的持有成本。用零借券费回测硬空头，等于把稀缺证券的租金算进 alpha。</p><footer>—— 据 D&#39;Avolio, 2002；Cohen, Diether and Malloy, Journal of Finance, 2007 整理</footer></div><p>上一课<a href="/quant/margin-securities-lending">融资融券机制</a>给出可借集合与召回。本课把资格换成价格：借券费率（loan fee / rebate 的另一面）。资金成本课会把各项摩擦收成 alpha 底；本课只把空头特有的券息钉死。不重写可借名单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一般抵押券（GC）借券费接近零或甚至有 rebate；热门券（special）费率可以高到年化数十个百分点，并按日重置。Cohen–Diether–Malloy 把借券费与未来回报联系起来：贵的空头往往随后下跌，但扣除费用后可实施利润变薄。缺口是回测的空头腿必须乘上<strong>当时费率</strong>，费率本身也要 PIT：用后来才变得 special 的费率回填过去，或用样本均值费率，都会错。</p><p>零费率假设对大盘股大致无害，对质量空头、小市值、新股、并购目标有害——恰好是异象空头最爱待的地方。</p><h3 id="借券费不是融券利息那么一个数" tabindex="-1">借券费不是融券利息那么一个数 <a class="header-anchor" href="#借券费不是融券利息那么一个数" aria-label="Permalink to &quot;借券费不是融券利息那么一个数&quot;">​</a></h3><p>融资利率是借钱的价格；借券费是借券的价格。空头同时可能付融资相关成本与借券费，取决于账户如何记账。把两笔合成一个「融券日利率」可以，但来源要拆得开，否则后课回购与资金底会重复扣或漏扣。Rebate 下降就是借券变贵，符号要与费用支出一致。</p><p><span class="marginnote">费率数据本身稀缺、且 vendor 常有延迟。用公开的 indicative fee 当成交费率，会偏乐观：真正借到热门券的成交价往往更差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每日对每条空头持仓计入当时借券费，可用日期取费率发布日或库存报价日，不得用期末 special 状态回填。无费率数据时，至少按可借性分档给惩罚（GC / 中等 / special），并做敏感性，而不是当零。召回日除了缺口价，还要停计此后未持有期间的费——不要在回补后仍扣费，也不要在未能开仓的日子「节省」了从未付出的费还当收益。</p><p>多头融资利率下一课回购与再后课资金底再收；本课不要把 GC 融资利率写进借券费。</p>',12)),(e(),s(c,null,{default:i(()=>[d(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GC%5B%22%E4%B8%80%E8%88%AC%E6%8A%B5%E6%8A%BC%20%E4%BD%8E%E8%B4%B9%E7%8E%87%22%5D%20--%3E%20COST%5B%22%E7%A9%BA%E5%A4%B4%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%22%5D%0A%20%20SP%5B%22special%20%E9%AB%98%E8%B4%B9%E7%8E%87%22%5D%20--%3E%20COST%0A%20%20COST%20--%3E%20NET%5B%22%E6%89%A3%E8%B4%B9%E5%90%8E%E7%A9%BA%E5%A4%B4%E6%94%B6%E7%9B%8A%22%5D%0A%20%20ZERO%5B%22%E9%9B%B6%E8%B4%B9%E7%8E%87%E5%81%87%E8%AE%BE%22%5D%20--%3E%20BIAS%5B%22%E6%8A%8A%E7%A7%9F%E9%87%91%E7%AE%97%E8%BF%9B%20alpha%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>无费率时分档惩罚，默认档不得为零。indicative 偏乐观，扣完若 alpha 已没，实盘更不会剩。召回后停计费；未开成的空头不是「低成本优势」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>借券费是出借人的租金，补偿借出期间不能卖出或投票、以及对手方风险。供给紧时费率跳升，同时上一课的召回更频繁：成本与强制回补正相关。于是纸面 PEAD 空头、应计空头在拥挤期看起来最赚钱，实盘却在付 special 费或根本开不出仓。这是资金约束修正因子收益的标准通道，不是「市场无效消失」的哲学结论——先把费扣掉，再谈剩余。</p><p><span class="marginnote">后课做空规则（报升）限制的是成交方式；本课限制的是持有成本。两者都让空头纸面收益偏高，机制不同。</span></p><p>每日空头市值乘当时 indicative 或成交费率，计入账单。无数据时按 GC / 中等 / special 分档给惩罚，并报告区间，默认档不得为零。费率 as-of 取报价日，禁止用个券历史最高费率或样本均值替代危机周。召回后停计费；未开成的空头不得因为「没付费」而在相对比较里显得更优——那是没有暴露，不是低成本。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不估计借券市场的结构模型，不把证券借贷做成权益互换定价全文。下一课<a href="/quant/repo-collateral">回购与抵押品</a>转向现金融资与 haircut。后课默认：空头损益含 PIT 借券费；零费率只允许作为大盘 GC 的对照，不能当默认。</p><p>后课回购谈的是借钱的折扣；本课是借券的租金。两笔都进资金底，但来源分开，避免重复扣。indicative 费率偏乐观这一点要写进局限：真实 special 成交往往更贵，因此扣 indicative 之后若 alpha 已消失，实盘更不会剩。</p><p>后课默认空头损益含 PIT 借券费；零费率只允许作为大盘 GC 对照，不能当空头腿的默认。</p><p>费率按日重置，持有期越长越不能用开仓日费率冻住。special 状态可以在一周内出现和消失，PIT 费率序列应与可借名单一起更新，而不是按月均值摊到每一个持有日。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可借是资格，费率是空头租金。</li><li>special 费率按日变，必须 PIT，禁止终局回填。</li><li>零费率把稀缺租金记进 alpha，偏差集中在异象空头。</li><li>费率与召回正相关，拥挤期纸面收益最不可实施。</li><li>融资利率不要与借券费混成一笔糊涂账。</li><li>出处：D&#39;Avolio (2002)；Cohen, Diether and Malloy (2007)。</li></ul>',12))])}const T=o(h,[["render",E]]);export{C as __pageData,T as default};
